const items = [
  // --- map skills
  mcq('mp.order', 'maps', 'In a grid reference, which comes first?', [['Eastings, read along the bottom', true], ['Northings, read up the side of the map', false, '“Along the corridor, then up the stairs”: eastings first.'], ['Whichever line is nearer the place', false, 'No: always eastings first, or you end up somewhere else entirely.']], 'Along the corridor (eastings), then up the stairs (northings).'),
  mcq('mp.six', 'maps', 'A church is in the square with easting 34 and northing 56. It is 7 tenths of the way across and 2 tenths of the way up. What is its six-figure grid reference?', [['347562', true], ['345672', false, 'Write the easting with its tenth (347), then the northing with its tenth (562).'], ['562347', false, 'Eastings first.'], ['3456', false, 'That is the four-figure reference for the square; six figures add the tenths.']], 'Easting 34 + 7 tenths = 347; northing 56 + 2 tenths = 562. So 347562.'),
  fact('mp.accuracy', 'maps', 'On a 1:25 000 or 1:50 000 OS map, a six-figure grid reference locates a point to within how many metres?', '100 metres', ['1 metre', '10 kilometres', '1 kilometre'], 'Grid squares are 1 km; tenths of a square are 100 m.', C),
  mcq('mp.contours', 'maps', 'Contour lines on a map are very close together. What does that tell you?', [['The slope is steep', true], ['The land is flat', false, 'Flat land has contours far apart, or none at all.'], ['There is a river', false, 'Rivers are blue lines. Close contours show steepness.'], ['It is a forest', false, 'Woodland has its own green symbol.']], 'Each contour joins points of equal height. Close together means the height changes quickly over a short distance.'),
  fact('mp.scale', 'maps', 'On a 1:50 000 map, how many centimetres represent 1 kilometre?', '2', ['4', '5', '50'], '1 km = 100 000 cm. 100 000 ÷ 50 000 = 2 cm. (On a 1:25 000 map it is 4 cm.)'),
  fact('mp.bearing-e', 'maps', 'What is the bearing of due east?', '090°', ['045°', '180°', '270°'], 'Bearings are measured clockwise from north, always with three figures: north 000°, east 090°, south 180°, west 270°.', { accept: ['090', '90', '90°'] }),
  fact('mp.bearing-sw', 'maps', 'What is the bearing of south-west?', '225°', ['135°', '315°', '250°'], 'South is 180°; south-west is halfway on to west (270°): 225°.', { accept: ['225'] }),
  mcq('mp.trig', 'maps', 'On an OS map, what does a small blue triangle with a dot in the middle show?', [['A trig point on a hilltop', true], ['A campsite with toilets and water', false, 'Campsites have a tent symbol.'], ['A church with a tower or spire', false, 'Churches are shown by a black square or circle with a cross.'], ['A youth hostel or mountain hut', false, 'Hostels have a red triangle symbol.']], 'Trig points are concrete pillars on hilltops, once used to survey Britain.'),
  mcq('mp.spot', 'maps', 'What is a spot height?', [['An exact height in metres, marked by a dot', true], ['The highest point shown on that map sheet', false, 'Spot heights appear all over a map.'], ['A viewpoint with a wide view of the land', false, 'Viewpoints have their own symbol; a spot height is a number beside a dot.']], 'Spot heights fill in detail between contour lines.'),

  // --- tectonics
  fact('tc.layers', 'tectonics', 'What is the thin, rocky outer layer of the Earth called?', 'the crust', ['the mantle', 'the outer core', 'the inner core'], 'Continental crust is about 30–50 km thick; oceanic crust only about 7 km.', { accept: ['crust'] }),
  mcq('tc.core', 'tectonics', 'Which layer of the Earth is liquid metal?', [['The outer core', true], ['The inner core', false, 'The inner core is solid, despite the heat, because of the enormous pressure.'], ['The mantle', false, 'The mantle is solid rock that flows extremely slowly.'], ['The crust', false, 'The crust is solid rock.']], 'The liquid iron and nickel of the outer core create the Earth’s magnetic field.'),
  mcq('tc.move', 'tectonics', 'What do most geologists now think mainly drives the plates?', [['Slab pull and ridge push', true], ['The pull of the Moon’s gravity', false, 'Tides move water, not plates.'], ['The Earth’s spin flinging them outwards', false, 'The Earth’s rotation is far too gentle a force to move plates.'], ['Earthquakes shoving the plates along', false, 'Earthquakes are a result of plate movement, not the cause.']], 'Older textbooks say convection currents; current thinking puts more weight on dense oceanic plates sinking (slab pull) and new rock pushing out from ridges (ridge push).'),
  mcq('tc.destructive', 'tectonics', 'At a destructive plate boundary such as the west coast of South America, what happens?', [['The oceanic plate sinks under the continental plate', true], ['The plates move apart and magma rises to form new crust', false, 'That is a constructive boundary.'], ['The two plates slide past each other sideways', false, 'That is a conservative boundary.'], ['The continental plate sinks under the oceanic plate', false, 'The denser plate sinks, and oceanic crust is denser than continental crust.']], 'The Nazca Plate subducts beneath the South American Plate, building the Andes.'),
  mcq('tc.constructive', 'tectonics', 'Why is Iceland slowly getting wider?', [['Two plates are pulling apart beneath it', true], ['Lava drifts across the ocean floor from Hawaii', false, 'Hawaii is a hotspot in the Pacific.'], ['Falling sea levels are uncovering more land', false, 'The plates are moving apart, about 2 cm a year.'], ['Melting glaciers let the land spread outwards', false, 'It is plate movement.']], 'The Mid-Atlantic Ridge runs through Iceland: the North American and Eurasian plates move apart and magma fills the gap.'),
  mcq('tc.conservative', 'tectonics', 'The San Andreas Fault in California is a famous example of which kind of boundary?', [['Conservative: plates slide past', true], ['Constructive: plates pull apart', false, 'No new crust forms there.'], ['Destructive: one plate sinks under', false, 'No plate sinks there.'], ['Collision: two continents meet', false, 'Collision boundaries build mountain ranges like the Himalayas.']], 'No volcanoes, but powerful earthquakes when the stuck plates jerk past each other.'),
  fact('tc.himalayas', 'tectonics', 'The Himalayas formed where which two plates collide?', 'the Indian and Eurasian plates', ['the Pacific and Nazca plates', 'the African and South American plates', 'the North American and Eurasian plates'], 'India is still pushing north, so Everest is still rising by a few millimetres a year.', C),
  fact('tc.ring', 'tectonics', 'What is the name for the belt of volcanoes and earthquakes around the Pacific Ocean?', 'the Ring of Fire', ['the Rim of Ash', 'the Pacific Ridge', 'the Hot Spot'], 'About three-quarters of the world’s active volcanoes are in this belt.', { accept: ['ring of fire', 'pacific ring of fire'] }),
  mcq('tc.magnitude', 'tectonics', 'On the magnitude scale, how much more energy does a magnitude 7 earthquake release than a magnitude 6?', [['About 32 times as much', true], ['Only a little more: it is one step up', false, 'The scale is logarithmic.'], ['Twice as much', false, 'Much more than twice.'], ['A million times as much', false, 'Far too many.']], 'Each whole step is about 10 times the ground shaking and about 32 times the energy.'),

  // --- hazards: case studies
  fact('hz.nepal', 'hazards', 'In which year did the Gorkha earthquake (magnitude 7.8) strike Nepal, killing about 9,000 people?', '2015', ['2004', '2010', '2023'], 'It struck on 25 April 2015 and set off avalanches on Everest.'),
  mcq('hz.haiti', 'hazards', 'The 2010 Haiti earthquake (magnitude 7.0) killed well over 100,000 people. What was the MAIN reason the death toll was so high?', [['Weak, crowded buildings near the epicentre', true], ['It was the strongest earthquake ever recorded', false, 'Magnitude 7.0 is strong but far from the largest: Chile 1960 was 9.5.'], ['It struck at night while people slept', false, 'It struck just before 5 pm; the weak buildings were the main reason.'], ['Haiti had never had an earthquake before', false, 'Haiti sits near a plate boundary; the issue was vulnerability.']], 'The same magnitude kills very different numbers of people depending on buildings, wealth and preparation.'),
  mcq('hz.iceland', 'hazards', 'The 2010 eruption of Eyjafjallajökull in Iceland killed no one. What problem did it cause across Europe?', [['Its ash closed European airspace', true], ['A tsunami flooded the coast of Norway', false, 'There was no tsunami.'], ['Lava flowed into the North Atlantic', false, 'Lava stayed in Iceland.'], ['It caused the 2010 Haiti earthquake', false, 'They are thousands of kilometres apart and unconnected.']], 'About 100,000 flights were cancelled: a reminder that hazards have global, economic effects.'),
  mcq('hz.thera', 'hazards', 'About 3,600 years ago, the volcano on Thera (Santorini) erupted. What does the island look like today because of it?', [['A ring of islands round a flooded crater', true], ['A tall cone-shaped mountain above the sea', false, 'The middle of the volcano collapsed into the sea.'], ['A flat island of black volcanic sand', false, 'Its famous cliffs are the caldera walls.'], ['It sank completely beneath the waves', false, 'Much of it survives as a crescent of islands.']], 'The Minoan eruption buried the Bronze Age town of Akrotiri. Some people link it to the legend of Atlantis.'),
  mcq('hz.primary', 'hazards', 'Which of these is a SECONDARY effect of an earthquake?', [['Disease from damaged water supplies', true], ['Buildings collapsing during the shaking', false, 'That happens straight away: a primary effect.'], ['Gas pipes snapping as the ground moves', false, 'That happens at the moment of the quake: a primary effect.'], ['Roads and bridges cracking apart', false, 'Direct damage is primary.']], 'Primary effects happen at once; secondary effects follow later as a result: fires, disease, homelessness, lost jobs.'),
  mcq('hz.japan', 'hazards', 'In 2011, a magnitude 9.0 earthquake struck off Japan. What caused most of the deaths?', [['The tsunami that followed it', true], ['Buildings falling in Tokyo', false, 'Japan’s strict building rules meant most buildings survived the shaking.'], ['Volcanic eruptions', false, 'No eruption was involved.'], ['A heatwave', false, 'It was March.']], 'The tsunami swept up to 10 km inland and damaged the Fukushima nuclear power station.'),
  mcq('hz.live', 'hazards', 'Why do millions of people live near active volcanoes such as Vesuvius?', [['Fertile soils, tourism and geothermal energy', true], ['They do not know the volcano is still active', false, 'Most know very well.'], ['Volcanoes rarely erupt more than once', false, 'Vesuvius erupted in AD 79 and many times since, most recently in 1944.'], ['The government forbids them to move away', false, 'It is a choice, often for good reasons.']], 'Benefits and risks are weighed every day by people living with hazards.'),

  // --- weather and rainfall
  mcq('wx.low', 'weather', 'What kind of weather does a low-pressure system (a depression) usually bring to the UK?', [['Cloud, wind and rain', true], ['Clear skies and calm air', false, 'That is high pressure.'], ['Heavy snow, whatever the season', false, 'Only if it is cold enough.'], ['Fog and frost but no wind', false, 'Fog and frost come with high pressure in winter.']], 'Rising air cools, water vapour condenses into clouds, and rain follows.'),
  mcq('wx.high', 'weather', 'Why does high pressure often bring clear skies?', [['Air is sinking and warming, so clouds do not form', true], ['High pressure pushes clouds away like a broom', false, 'It is about sinking air, not pushing.'], ['The Sun is closer', false, 'The Sun’s distance has nothing to do with it.']], 'Anticyclones bring sunny summer days and cold, frosty or foggy winter nights.'),
  mcq('wx.relief', 'weather', 'Why is the west of Britain (e.g. the Lake District) much wetter than the east?', [['Relief rain: moist winds rise over the hills', true], ['The west is nearer the Equator than the east', false, 'They are at similar latitudes.'], ['The east is too warm for clouds to form', false, 'The east is in a rain shadow, but it still has clouds.'], ['Sea spray from the Atlantic falls as rain', false, 'Rain comes from clouds; the key is air rising over the hills.']], 'The prevailing wind comes from the south-west, across the warm Atlantic.'),
  fact('wx.convection', 'weather', 'Heavy afternoon thunderstorms in the tropics, caused by strong sunshine heating the ground, are an example of which type of rainfall?', 'convectional', ['relief', 'frontal', 'acid'], 'Hot ground heats the air, which rises fast, cools and forms towering clouds.', { accept: ['convectional rainfall', 'convection'] }),
  fact('wx.frontal', 'weather', 'Rain caused when warm air rises over a wedge of colder air is called…', 'frontal rainfall', ['relief rainfall', 'convectional rainfall', 'acid rain'], 'This happens at the fronts of a depression, which is why UK forecasts show warm and cold fronts.', C),
  mcq('wx.drift', 'weather', 'Why are UK winters much milder than those of places at the same latitude in Canada?', [['The warm North Atlantic Drift', true], ['The UK is closer to the Sun', false, 'Same latitude, same sunlight.'], ['The UK is lower above sea level', false, 'Height is not the reason.'], ['Cold Arctic air never reaches the UK', false, 'Arctic air does reach the UK; the warm ocean current is the difference.']], 'This is one reason the UK has a mild, wet maritime climate.'),
  mcq('wx.med', 'weather', 'What is a Mediterranean climate like?', [['Hot, dry summers and mild, wet winters', true], ['Cold winters with snow and cool, wet summers', false, 'That is closer to a cold continental climate.'], ['Hot and wet all year, with daily storms', false, 'That is equatorial.'], ['Hot summers with heavy rain, dry winters', false, 'It is the other way round: summers are dry.']], 'Greece, southern Italy and southern Spain have it, which is why olives and vines grow so well there.'),
  mcq('wx.graph', 'weather', 'On a climate graph, how are temperature and rainfall usually shown?', [['Temperature as a line, rainfall as bars', true], ['Both as pie charts, one per season', false, 'Pie charts show proportions, not monthly change.'], ['Temperature as bars, rainfall as a line', false, 'The other way round: bars are for rainfall.'], ['Rainfall as a line, with no temperature', false, 'Both are shown, on two axes.']], 'One axis is temperature (°C), the other rainfall (mm).'),

  // --- climate change
  mcq('cc.green', 'climate', 'What is the enhanced greenhouse effect?', [['Human-made gases trapping extra heat', true], ['A hole in the ozone layer letting in heat', false, 'The ozone hole is a separate problem (about ultraviolet light).'], ['Heat escaping from greenhouses and buildings', false, 'Real greenhouses are only an analogy.'], ['The Sun giving out more energy each year', false, 'The Sun’s output has not risen enough to explain recent warming.']], 'The natural greenhouse effect keeps Earth habitable; burning fossil fuels has strengthened it.'),
  fact('cc.co2', 'climate', 'About how much carbon dioxide was in the air before the Industrial Revolution, in parts per million?', 'about 280', ['about 28', 'about 2,800', 'about 28,000'], 'Today it is about 427 parts per million (the 2025 average), peaking above 430 each May: higher than at any time in at least 800,000 years, as ice cores show.', C),
  mcq('cc.evidence', 'climate', 'Which of these is EVIDENCE that the climate is changing?', [['Ice cores and retreating glaciers', true], ['One record-breaking cold winter', false, 'A single season is weather, not climate.'], ['Weather forecasts being wrong more often', false, 'Forecast accuracy is not evidence of climate change.'], ['Rising sales of fans and air conditioners', false, 'Sales are not a scientific measurement of climate.']], 'Climate is measured over decades; many independent kinds of evidence agree.'),
  mcq('cc.natural', 'climate', 'Which is a NATURAL cause of climate change?', [['Changes in the Earth’s orbit', true], ['Burning coal in power stations', false, 'Human cause.'], ['Methane from cattle farming', false, 'Human cause (methane).'], ['Cutting down the rainforests', false, 'Human cause.']], 'Orbital cycles, volcanic eruptions and changes in the Sun’s output have changed climate in the past.'),
  mcq('cc.methane', 'climate', 'Which greenhouse gas comes especially from cattle, rice paddies and landfill sites?', [['Methane', true], ['Oxygen', false, 'Oxygen is not a greenhouse gas.'], ['Nitrogen', false, 'Nitrogen is not a greenhouse gas.'], ['Helium', false, 'Helium is not a greenhouse gas.']], 'Methane traps far more heat per molecule than carbon dioxide, though it lasts less time in the air.'),
  mcq('cc.paris', 'climate', 'What did countries agree in the 2015 Paris Agreement?', [['To keep warming well below 2 °C', true], ['To ban all petrol cars by 2020', false, 'No such ban was agreed.'], ['To stop all warming immediately', false, 'Some warming is already locked in.'], ['To stop using all coal by 2016', false, 'No such deadline was agreed.']], 'Each country sets its own targets and updates them every five years.'),
  mcq('cc.mitigate', 'climate', 'What is the difference between mitigation and adaptation?', [['Mitigation cuts causes; adaptation copes with effects', true], ['They are two words for the same response', false, 'They are two different responses.'], ['Mitigation is building sea walls and flood barriers', false, 'Sea walls are adaptation.'], ['Adaptation is planting forests to soak up CO₂', false, 'That reduces the cause: mitigation.']], 'Good policy needs both.'),
  mcq('cc.effects', 'climate', 'Which is a likely effect of climate change on the UK?', [['Hotter summers and wetter winters', true], ['A new ice age within ten years', false, 'Not supported by evidence.'], ['Colder summers and drier winters', false, 'Changes are already measured.'], ['Rain disappearing completely', false, 'Winters are expected to get wetter.']], 'The UK’s record of 40.3 °C was set at Coningsby, Lincolnshire, in July 2022.'),

  // --- rivers
  order('rv.course', 'rivers', 'Put these river features in order from source to mouth.', ['V-shaped valley and waterfall', 'meanders', 'floodplain and levees', 'estuary'], ['upper course', 'middle course', 'lower course', 'mouth'], 'Erosion dominates high up; deposition dominates near the sea.'),
  mcq('rv.hydraulic', 'rivers', 'What is hydraulic action?', [['Water forcing air into cracks in the bank', true], ['Rocks carried by the river scraping the bed', false, 'That is abrasion.'], ['Rocks knocking into each other and breaking', false, 'That is attrition.'], ['Rock dissolving slowly in the water', false, 'That is solution.']], 'The four erosion processes: hydraulic action, abrasion, attrition and solution.'),
  mcq('rv.saltation', 'rivers', 'Small pebbles bouncing along a river bed are being transported by…', [['saltation', true], ['traction', false, 'Traction is large boulders rolled along the bed.'], ['suspension', false, 'Suspension is fine particles carried in the water.'], ['solution', false, 'Solution is dissolved minerals.']], 'Traction, saltation, suspension and solution: from the heaviest load to the lightest.'),
  order('rv.oxbow', 'rivers', 'Put the formation of an oxbow lake in order.', ['Erosion on the outside of bends makes the meander loop tighter', 'The neck of the meander narrows', 'In a flood the river cuts through the neck', 'Deposition seals off the old loop as an oxbow lake'], null, 'Erosion on the outer bank and deposition on the inner bank make meanders migrate until the neck is breached.'),
  mcq('rv.waterfall', 'rivers', 'Why do waterfalls such as High Force on the River Tees form?', [['Soft rock under hard rock erodes faster', true], ['A volcano pushes the riverbed up suddenly', false, 'No volcano involved.'], ['People dug them to power water mills', false, 'They are natural.'], ['The sea level dropped suddenly long ago', false, 'It is about differences in rock hardness.']], 'The hard rock overhang collapses and the waterfall retreats upstream, leaving a gorge.'),
  fact('rv.levee', 'rivers', 'Raised banks of sediment along a river in its lower course, built up by repeated floods, are called…', 'levees', ['groynes', 'spits', 'meanders'], 'When the river floods, it drops its heaviest sediment first, right beside the channel.', { accept: ['levee'] }),
  mcq('rv.hard', 'rivers', 'Which of these is SOFT engineering for flood management?', [['Planting trees upstream', true], ['Building a concrete flood wall', false, 'Hard engineering.'], ['Straightening the river channel', false, 'Hard engineering.'], ['Building a dam and reservoir', false, 'Hard engineering.']], 'Soft engineering works with natural processes; it is usually cheaper and better for wildlife, but protects less in extreme floods.'),
  fact('rv.barrier', 'rivers', 'Which barrier, completed in 1982, protects London from tidal surges up the Thames?', 'the Thames Barrier', ['the Severn Barrage', 'the Humber Bridge', 'the Hoover Dam'], 'It is closed when a high tide and a storm surge from the North Sea arrive together.', { accept: ['thames barrier'] }),
  mcq('rv.nile', 'rivers', 'Which statement about the world’s great rivers is correct?', [['The Amazon carries the most water', true], ['The Thames is the longest in the world', false, 'The Thames is about 346 km; the Nile is over 6,600 km.'], ['The Amazon flows through central Africa', false, 'It is in South America.'], ['The Nile flows south into the Indian Ocean', false, 'It flows north into the Mediterranean.']], 'Some measurements make the Amazon longer: geographers still argue.'),

  // --- coasts
  mcq('cs.waves', 'coasts', 'What are destructive waves like?', [['Tall and frequent, with a strong backwash that drags material away', true], ['Low and gentle, with a strong swash that builds beaches', false, 'That describes constructive waves.'], ['Only found in harbours', false, 'They are common in storms everywhere.']], 'Destructive waves erode; constructive waves deposit.'),
  order('cs.stack', 'coasts', 'Put the erosion of a headland in order.', ['crack', 'cave', 'arch', 'stack', 'stump'], null, 'Hydraulic action and abrasion widen a crack into a cave; the cave breaks through as an arch; the arch collapses leaving a stack, which wears down to a stump. Old Harry Rocks in Dorset are famous chalk stacks.'),
  mcq('cs.drift', 'coasts', 'What is longshore drift?', [['Waves moving sand along the coast', true], ['The tide carrying sand in and out', false, 'Tides are caused mainly by the Moon.'], ['Cliffs slumping into the sea', false, 'That is mass movement.'], ['Wind blowing sand inland into dunes', false, 'That builds sand dunes; longshore drift moves sand along the coast.']], 'Swash moves material up the beach at an angle with the prevailing wind; backwash pulls it straight back down.'),
  fact('cs.spit', 'coasts', 'A long ridge of sand or shingle built out into the sea by longshore drift, such as Spurn Head, is called a…', 'spit', ['stack', 'groyne', 'stump'], 'Spits form where the coastline changes direction, for example at a river mouth.', { accept: ['a spit'] }),
  mcq('cs.holderness', 'coasts', 'The Holderness coast in Yorkshire is eroding by about 2 metres a year. Why so fast?', [['Its cliffs are soft boulder clay', true], ['Its cliffs are hard granite', false, 'Granite is very resistant.'], ['Quarries are digging the cliffs away', false, 'It is natural erosion of soft clay.'], ['The tides there are unusually high', false, 'The tidal range is not the reason: the soft clay is.']], 'It is one of the fastest-eroding coastlines in Europe; villages recorded in the Domesday Book are now under the sea.'),
  mcq('cs.groyne', 'coasts', 'What do groynes do?', [['Trap sand moving along the beach', true], ['Stop the tide coming in too far', false, 'Nothing stops the tide.'], ['Break up waves out at sea', false, 'That is an offshore reef or breakwater; groynes run down the beach.'], ['Hold up the pier and promenade', false, 'They are fences down the beach.']], 'But they can starve beaches further along the coast of sand, increasing erosion there.'),
  mcq('cs.retreat', 'coasts', 'What is managed retreat?', [['Letting the sea flood some low land', true], ['Building a new sea wall further out to sea', false, 'That is advancing the line.'], ['Moving a whole city inland at once', false, 'It is planned, gradual change to the coastline.'], ['Removing old groynes from the beach', false, 'That is not the plan: low land is allowed to flood and become salt marsh.']], 'Salt marshes absorb wave energy and are excellent habitats, so managed retreat can be cheaper and greener.'),
  mcq('cs.choice', 'coasts', 'Why might a council decide NOT to protect an eroding stretch of coast?', [['The defences cost more than the land is worth', true], ['Erosion is impossible to measure accurately', false, 'It can be measured precisely.'], ['The law forbids building any sea walls', false, 'Sea walls are allowed.'], ['Erosion always stops by itself in time', false, 'It does not.']], 'Cost–benefit analysis is central to shoreline management plans, though it is hard on the people affected.'),

  // --- ice
  mcq('ic.corrie', 'ice', 'How does a corrie (also called a cirque or cwm) form?', [['Ice in a mountain hollow deepens it', true], ['A meteorite strikes a mountainside', false, 'Glaciers, not meteorites.'], ['A mountain stream carves it out', false, 'Rivers make V-shaped valleys.'], ['Strong winds scour it out', false, 'Ice is the cause.']], 'When the ice melts, many corries hold a small lake called a tarn.'),
  fact('ic.arete', 'ice', 'A sharp knife-edge ridge between two corries, such as Striding Edge on Helvellyn, is called an…', 'arête', ['esker', 'erratic', 'estuary'], 'Where three or more corries meet, a pyramidal peak can form.', { accept: ['arete'] }),
  mcq('ic.ushape', 'ice', 'How can you tell a valley was carved by a glacier?', [['It is U-shaped, with a flat floor and steep sides', true], ['It is V-shaped with interlocking spurs', false, 'That is a river valley.'], ['It has a river delta', false, 'Deltas form at river mouths.'], ['It is full of sand dunes', false, 'Dunes are coastal or desert landforms.']], 'Glaciers fill the whole valley and grind it into a U shape, cutting off spurs.'),
  fact('ic.ribbon', 'ice', 'Long, thin lakes in glacial valleys, such as Windermere, are called…', 'ribbon lakes', ['oxbow lakes', 'tarns', 'lagoons'], 'Ice eroded the softer rock of the valley floor more deeply, leaving a long basin.', { accept: ['ribbon lake'] }),
  fact('ic.erratic', 'ice', 'A boulder carried by ice and dropped far from where it came from is called an…', 'erratic', ['arête', 'esker', 'oxbow'], 'Erratics help geologists track how ice moved.', { accept: ['glacial erratic', 'an erratic'] }),
  fact('ic.when', 'ice', 'About how long ago was the last glacial maximum, when ice sheets were largest in Britain?', 'about 20,000 years ago', ['about 2,000 years ago', 'about 2 million years ago', 'about 200 years ago'], 'The ice had melted from Britain by about 11,700 years ago.', C),

  // --- biomes
  order('bm.layers', 'biomes', 'Put the layers of a tropical rainforest in order, from the top down.', ['emergent layer', 'canopy', 'understorey', 'forest floor'], null, 'Emergents tower above the canopy, which captures most of the light.'),
  mcq('bm.soil', 'biomes', 'Why are tropical rainforest soils surprisingly poor in nutrients?', [['Nutrients are locked up in the plants', true], ['Hardly any dead leaves fall to the ground', false, 'There are plenty, but they decompose very quickly.'], ['It is too cold for leaves to decompose', false, 'It is hot, so decomposition is fast.'], ['The roots grow on bare rock with no soil', false, 'They have soil, just thin and poor.']], 'This is why cleared rainforest land often becomes infertile within a few years.'),
  mcq('bm.amazon', 'biomes', 'What is the biggest single cause of deforestation in the Amazon?', [['Clearing land for cattle ranching', true], ['Building theme parks', false, 'Not a significant cause.'], ['Volcanic eruptions', false, 'There are no active volcanoes in the Amazon basin.'], ['Forest fires started by lightning', false, 'Most fires there are set by people to clear land.']], 'Soya farming, logging, mining and roads matter too.'),
  fact('bm.desert', 'biomes', 'A hot desert receives less than about how much rain a year?', '250 mm', ['2,500 mm', '500 mm', '1,000 mm'], 'The Sahara is the largest hot desert; some parts get almost no rain for years.', C),
  mcq('bm.cactus', 'biomes', 'Which is an adaptation of a cactus to the desert?', [['Spines instead of leaves', true], ['Huge flat leaves to catch sunlight', false, 'Big leaves lose too much water.'], ['Deep roots used only in winter months', false, 'Many cactus roots spread widely and shallowly to catch brief rain.'], ['Bright flowers open all year round', false, 'Flowering is brief.']], 'Spines also shade the plant and protect its stored water from animals.'),
  fact('bm.permafrost', 'biomes', 'Ground in the tundra that stays frozen all year round is called…', 'permafrost', ['tarmac', 'ice cap', 'glacier'], 'As it thaws with climate change, it releases methane.', { accept: ['permafrost'] }),
  mcq('bm.foodweb', 'biomes', 'In an ecosystem, what is a producer?', [['A plant that makes its own food', true], ['An animal that eats only plants', false, 'That is a primary consumer.'], ['A decomposer such as fungi or bacteria', false, 'Decomposers break down dead matter.'], ['The top predator in the food web', false, 'Top predators are consumers.']], 'All food chains start with producers capturing the Sun’s energy.'),

  // --- population and migration
  fact('pp.eight', 'population', 'Roughly how many people live on Earth today?', 'about 8 billion', ['about 8 million', 'about 800 million', 'about 80 billion'], 'The world passed 8 billion in 2022, according to the UN.', C),
  order('pp.dtm', 'population', 'Put the stages of the demographic transition model in order.', ['high birth rate, high death rate, slow growth', 'death rate falls, rapid growth', 'birth rate falls, growth slows', 'low birth and death rates, stable', 'death rate higher than birth rate, decline'], ['stage 1', 'stage 2', 'stage 3', 'stage 4', 'stage 5'], 'Medicine and clean water cut deaths first; birth rates fall later, as education, contraception and urban living spread.'),
  mcq('pp.japan', 'population', 'Japan has an ageing, shrinking population. Which stage of the demographic transition model is it in?', [['Stage 5', true], ['Stage 1', false, 'Stage 1 has very high birth and death rates.'], ['Stage 2', false, 'Stage 2 has rapid growth.'], ['Stage 3', false, 'Japan’s population is now falling, not just slowing.']], 'Fewer workers must support more pensioners: a big challenge for health care and the economy.'),
  mcq('pp.india', 'population', 'Which country became the most populous in the world in 2023, according to UN estimates?', [['India', true], ['China', false, 'China was first for decades, but its population is now falling.'], ['the USA', false, 'The USA is third, with about 340 million.'], ['Nigeria', false, 'Nigeria is growing fast but has about 240 million people.']], 'Both India and China have more than 1.4 billion people.'),
  mcq('pp.push', 'population', 'Which of these is a PUSH factor for migration?', [['War or persecution at home', true], ['Better-paid jobs abroad', false, 'That pulls people towards a place.'], ['Good schools in another country', false, 'A pull factor.'], ['Family already living abroad', false, 'Usually a pull factor.']], 'Push factors drive people away; pull factors attract them.'),
  mcq('pp.refugee', 'population', 'What is the difference between a refugee and an economic migrant?', [['Refugees flee danger; economic migrants seek work', true], ['They are two names for the same people', false, 'International law treats them differently.'], ['Refugees always move to a much richer country', false, 'Most refugees live in neighbouring, often poorer, countries.'], ['Economic migrants are never allowed to move', false, 'Many move legally for work.']], 'Under the 1951 Refugee Convention, refugees have a right to protection.'),
  fact('pp.density', 'population', 'The number of people per square kilometre is called the population…', 'density', ['distribution', 'pyramid', 'structure'], 'Distribution is where people live; density is how crowded it is.', { accept: ['population density'] }),
  mcq('pp.pyramid', 'population', 'A population pyramid has a very wide base and narrow top. What does it suggest?', [['A high birth rate and a young population', true], ['An ageing population with few young people', false, 'An ageing population has a narrow base and wide top.'], ['A shrinking population with few births', false, 'A wide base shows many births.'], ['Very few people live beyond about 30', false, 'It shows fewer older people, but many still live well beyond 30.']], 'Niger’s pyramid looks like this; Japan’s looks almost like an upside-down pyramid.'),

  // --- cities
  fact('ct.mega', 'cities', 'A city with more than 10 million people is called a…', 'megacity', ['village', 'capital', 'market town'], 'In 1950 there were two megacities; today there are more than thirty.', { accept: ['mega city', 'mega-city'] }),
  fact('ct.half', 'cities', 'In about which year did more of the world’s people start living in towns and cities than in the countryside?', '2007', ['1907', '1950', '2050'], 'This uses each country’s own definition of “urban”. The UN expects about two-thirds of people to live in urban areas by 2050 on that measure; its 2025 report, using one standard definition for every country, counts 45% of people in cities and 36% in towns.'),
  mcq('ct.lagos', 'cities', 'Lagos, in Nigeria, is one of Africa’s largest cities. What drives its rapid growth?', [['Rural–urban migration and a high birth rate', true], ['People leaving to live in the countryside', false, 'That would shrink it.'], ['It became the capital in 2010', false, 'Abuja has been the capital since 1991.'], ['It has no jobs', false, 'It is Nigeria’s business and tech hub, which attracts people.']], 'Its growth brings opportunity (jobs, tech start-ups, ports) and challenges (housing, traffic, water, waste).'),
  mcq('ct.informal', 'cities', 'Dharavi in Mumbai and Makoko in Lagos are informal settlements. What does “informal” mean here?', [['Homes built without official permission', true], ['A relaxed resort for holidaymakers', false, 'Informal means built without official permission, not relaxed.'], ['Tower blocks built by the government', false, 'Those are formal housing.'], ['Empty land kept for future building', false, 'Hundreds of thousands of people live in each.']], 'Dharavi has a huge recycling industry and thousands of small businesses: seeing only poverty misses half the story.'),
  mcq('ct.london', 'cities', 'London grew enormously in the 1800s. Why?', [['Jobs and trade drew people in', true], ['The climate became warmer and drier', false, 'Climate was not the reason.'], ['The Romans rebuilt it as their capital', false, 'The Romans founded it in about AD 47–50.'], ['Farming around London became more popular', false, 'People left farming for city jobs.']], 'London had about 1 million people in 1801 and over 6 million by 1901: the same story megacities tell today.'),
  mcq('ct.sustainable', 'cities', 'Which feature makes a city more sustainable?', [['Good public transport and green spaces', true], ['More motorways leading into the centre', false, 'More traffic usually means more pollution.'], ['Building new homes on all its parks', false, 'Green spaces cool cities and reduce flooding.'], ['Sending all its waste to landfill sites', false, 'Recycling is more sustainable.']], 'Freiburg in Germany and Curitiba in Brazil are famous examples.'),

  // --- development
  mcq('dv.hdi', 'development', 'What does the Human Development Index (HDI) combine?', [['Life expectancy, education and income', true], ['GDP, exports and government debt', false, 'HDI was designed to go beyond income alone.'], ['Population, land area and birth rate', false, 'Those are not development measures.'], ['Numbers of cars, phones and computers', false, 'Not part of the HDI.']], 'It runs from 0 to 1; Norway, Switzerland and Iceland are usually near the top.'),
  fact('dv.gni', 'development', 'GNI per head means a country’s total income divided by…', 'its population', ['its area', 'the number of cities', 'its exports'], 'It is usually given in US dollars so that countries can be compared.', C),
  mcq('dv.brandt', 'development', 'What was the Brandt line (1980)?', [['A line between richer and poorer countries', true], ['The Equator, redrawn as a policy line', false, 'It wiggled: Australia and New Zealand were in the North.'], ['A railway built across West Germany', false, 'Willy Brandt led the report that drew it.'], ['The Greenwich Meridian through London', false, 'That is the Prime Meridian.']], 'Today countries such as China, Brazil and the Gulf states have grown so much that the line is far too simple.'),
  mcq('dv.infant', 'development', 'Why is the infant mortality rate a useful measure of development?', [['It reflects health care, water and food', true], ['It shows how many children go to school', false, 'That is the school enrolment rate.'], ['It measures a family’s wealth directly', false, 'It is a social measure.'], ['It counts the babies born each year', false, 'That is the birth rate.']], 'It is the number of babies per 1,000 born who die before their first birthday.'),
  mcq('dv.gap', 'development', 'Which is a PHYSICAL factor that can slow a country’s development?', [['Being landlocked', true], ['Corruption in the government', false, 'That is a political factor.'], ['High levels of national debt', false, 'An economic factor.'], ['A history of colonial rule', false, 'A historical factor.']], 'Most uneven development has several causes: physical, economic, political and historical.'),
  mcq('dv.aid', 'development', 'Which type of aid is often thought to do most good in the long term?', [['Small local projects, such as wells', true], ['Emergency food parcels every year', false, 'Emergency aid saves lives but does not build long-term change.'], ['Loans paid back with high interest', false, 'Debt can hold development back.'], ['Huge dams built by foreign firms', false, 'Large top-down projects can help, but often miss local needs.']], 'Bottom-up projects use appropriate technology that local people can maintain.'),

  // --- globalisation
  mcq('gb.what', 'global', 'What is globalisation?', [['Countries becoming more connected', true], ['Making accurate maps of the globe', false, 'That is cartography.'], ['Countries joining into one government', false, 'There is no single world government; globalisation is about connections.'], ['The whole planet warming up', false, 'Related, but not the definition.']], 'Containers, cheap flights and the internet have sped it up enormously since the 1970s.'),
  fact('gb.tnc', 'global', 'A company that operates in many countries, such as Apple or Toyota, is called a…', 'transnational corporation', ['registered charity', 'workers’ cooperative', 'nationalised industry'], 'TNCs often design products in one country and make them in others where costs are lower.', { accept: ['tnc', 'multinational', 'multinational company', 'transnational company'] }),
  mcq('gb.container', 'global', 'Why did the shipping container (from the 1950s) transform world trade?', [['Standard boxes move between ships and lorries', true], ['They made ships faster than planes', false, 'Ships are still slower than planes.'], ['They let goods skip customs checks', false, 'Goods still pass through customs.'], ['They are light enough to fly by air', false, 'They are heavy steel boxes, carried by sea.']], 'Over 80% of the world’s goods, by volume, travel by sea; Shanghai is the busiest container port.'),
  mcq('gb.tnc-pros', 'global', 'Which is a DISADVANTAGE when a TNC builds a factory in a lower-income country?', [['Profits may go back to the home country', true], ['It creates jobs', false, 'That is an advantage.'], ['Local people learn new skills', false, 'An advantage.'], ['Roads and power supplies may be improved', false, 'Usually an advantage.']], 'The 2013 Rana Plaza factory collapse in Bangladesh led to stronger safety campaigns.'),
  mcq('gb.fair', 'global', 'What is Fairtrade?', [['A scheme guaranteeing farmers a fair price', true], ['Trade with no import taxes at all', false, 'That is free trade.'], ['Buying only from nearby farms', false, 'That is buying local; Fairtrade is about prices for farmers.'], ['A market where prices are fixed by law', false, 'Fairtrade is a certification scheme, not a law.']], 'It helps producers of coffee, cocoa and bananas, among others.'),
  mcq('gb.suez', 'global', 'In 2021 a container ship, the Ever Given, blocked the Suez Canal for six days. Why did it matter worldwide?', [['About 12% of world trade used the canal', true], ['It flooded the towns along the canal', false, 'No flooding.'], ['It cut the undersea internet cables', false, 'Undersea cables were not affected.'], ['It stopped Egypt exporting its oil', false, 'Supply chains are global.']], 'Globalised supply chains are efficient, but fragile.'),

  // --- energy
  mcq('en.renew', 'energy', 'Which of these is a renewable energy source?', [['Wind', true], ['Coal', false, 'Fossil fuel: non-renewable.'], ['Natural gas', false, 'Fossil fuel.'], ['Uranium (nuclear)', false, 'Nuclear is low-carbon but uranium is not renewable.']], 'Renewables: wind, solar, hydroelectric, tidal, wave, geothermal and biomass.'),
  mcq('en.geo', 'energy', 'Iceland gets most of its electricity and heating from which two sources?', [['Hydro and geothermal', true], ['Coal and imported oil', false, 'Iceland uses very little fossil fuel for electricity.'], ['Nuclear and solar', false, 'It has no nuclear power stations.'], ['Wind and tidal power', false, 'Its rivers and volcanic heat do most of the work.']], 'Its position on the Mid-Atlantic Ridge gives it abundant volcanic heat.'),
  mcq('en.wind', 'energy', 'What is one disadvantage of wind power?', [['It stops when the wind drops', true], ['It gives off carbon dioxide while running', false, 'It produces almost none while running.'], ['The wind will run out one day', false, 'Wind is renewable.'], ['It only works well in deserts', false, 'The UK has some of Europe’s best wind.']], 'Batteries, pumped storage and links between countries help balance supply.'),
  mcq('en.water', 'energy', 'What is water stress?', [['When demand for water exceeds supply', true], ['When far too much rain falls at once', false, 'That is flooding.'], ['When rivers flow faster than usual', false, 'Fast rivers are not the point: it is about demand and supply.'], ['When water is too cold to drink safely', false, 'Temperature is not the point: it is about demand and supply.']], 'Parts of the Middle East use desalination plants to turn seawater into drinking water.'),
  mcq('en.food', 'energy', 'Why do some people try to buy food with fewer “food miles”?', [['To cut transport emissions', true], ['Local food is always much cheaper', false, 'Not always.'], ['Imported food has fewer vitamins', false, 'Freshness varies; the main aim is cutting transport emissions.'], ['Shops must charge more for it by law', false, 'There is no such law.']], 'It is not the whole story: food grown in heated greenhouses nearby can have a bigger footprint than food shipped in.'),
  mcq('en.mix', 'energy', 'What is a country’s “energy mix”?', [['All the sources it gets energy from', true], ['Its total energy use per person', false, 'That is consumption; the mix is the range of sources.'], ['Only the oil and gas it produces', false, 'It includes every source.'], ['The weather that affects its energy', false, 'Weather affects some sources, but the mix is the sources themselves.']], 'The UK’s mix has shifted from coal to gas, wind and other sources; its last coal power station closed in 2024.'),

  // --- Russia
  fact('ru.size', 'russia', 'Russia is the largest country in the world. About how many time zones does it span?', '11', ['3', '24', '6'], 'When it is morning in Kaliningrad, it is already evening in Kamchatka.'),
  fact('ru.urals', 'russia', 'Which mountain range is traditionally used as the boundary between Europe and Asia in Russia?', 'the Ural Mountains', ['the Alps', 'the Andes', 'the Pennines'], 'Most Russians live west of the Urals, in European Russia.', { accept: ['urals', 'ural mountains'] }),
  fact('ru.baikal', 'russia', 'Lake Baikal in Siberia is the deepest lake in the world. About how deep is it?', 'about 1,600 metres', ['about 16 metres', 'about 160 metres', 'about 16 kilometres'], 'It holds about a fifth of the world’s unfrozen fresh surface water.', C),
  mcq('ru.permafrost', 'russia', 'How does permafrost affect building in Siberia?', [['Buildings stand on stilts or piles', true], ['Buildings must be made of ice blocks', false, 'Buildings are ordinary materials, raised on piles.'], ['Nothing at all can be built there', false, 'Cities such as Yakutsk are built on permafrost.'], ['Buildings sit on heated concrete', false, 'Heating the ground would melt the permafrost and the building would sink.']], 'As the climate warms, thawing permafrost is cracking roads and buildings.'),
  fact('ru.rail', 'russia', 'The Trans-Siberian Railway from Moscow to Vladivostok is about how long?', 'about 9,300 km', ['about 930 km', 'about 93,000 km', 'about 300 km'], 'The journey takes about a week.', C),
  fact('ru.volga', 'russia', 'Which is the longest river in Europe, flowing through Russia into the Caspian Sea?', 'the Volga', ['the Danube', 'the Thames', 'the Rhine'], 'About 3,500 km long.', { accept: ['volga', 'river volga'] }),
  mcq('ru.biomes', 'russia', 'Travelling north through Russia, which order of biomes would you pass through?', [['Steppe, then taiga, then tundra', true], ['Rainforest, then desert, then tundra', false, 'Russia has no rainforest.'], ['Tundra, then taiga, then steppe', false, 'That is travelling south.'], ['Desert, then savanna, then ice', false, 'No savanna in Russia.']], 'The taiga is the largest forest on Earth.'),
  mcq('ru.resources', 'russia', 'Why is Russia important in world energy?', [['It has huge reserves of gas and oil', true], ['It makes most of the world’s solar panels', false, 'That is China.'], ['It has the world’s largest wind farms', false, 'Its wind power is small; its gas and oil matter most.'], ['It supplies most of the world’s uranium', false, 'Russia does mine uranium, but its gas and oil matter far more.']], 'Pipelines carry Siberian gas thousands of kilometres to customers.'),

  // --- the Aegean
  fact('ae.capital', 'aegean', 'What is the capital of Greece?', 'Athens', ['Sparta', 'Thessaloniki', 'Corinth'], 'Athens is named after the goddess Athena; the Parthenon on its Acropolis has stood for about 2,500 years.', { accept: ['athens'] }),
  fact('ae.olympus', 'aegean', 'What is the highest mountain in Greece, home of the gods in myth?', 'Mount Olympus', ['Mount Etna', 'Mount Parnassus', 'Mount Ida'], 'Olympus is about 2,918 m high, on the border of Thessaly and Macedonia.', { accept: ['olympus'] }),
  fact('ae.sea', 'aegean', 'Which sea lies between Greece and Turkey, scattered with islands?', 'the Aegean Sea', ['the Black Sea', 'the Red Sea', 'the North Sea'], 'In myth it is named after King Aegeus, who threw himself into it when he saw black sails on Theseus’s ship.', { accept: ['aegean', 'aegean sea'] }),
  fact('ae.crete', 'aegean', 'Which is the largest Greek island, home of the Minoans and the legend of the Minotaur?', 'Crete', ['Rhodes', 'Corfu', 'Santorini'], 'The palace of Knossos on Crete was excavated by Arthur Evans from 1900.', { accept: ['crete'] }),
  mcq('ae.quakes', 'aegean', 'Why does Greece have so many earthquakes?', [['The African Plate sinks beneath it', true], ['Poseidon strikes the ground with his trident', false, 'That was the ancient explanation; the evidence points to plate tectonics.'], ['Greece sits on the Mid-Atlantic Ridge', false, 'That runs through Iceland.'], ['Its old volcanoes are collapsing', false, 'Volcanoes like Thera exist, but most quakes come from the plates.']], 'This subduction zone (the Hellenic arc) also feeds the volcanoes of the southern Aegean, including Santorini.'),
  mcq('ae.olives', 'aegean', 'Why do olive trees grow so well in Greece?', [['They suit hot, dry summers', true], ['They need constant heavy rain', false, 'Far too dry in summer.'], ['They need cold, snowy winters', false, 'Olives hate long frosts.'], ['They grow best in volcanic ash', false, 'Some soils are volcanic, but the climate is the key.']], 'Small leathery leaves and deep roots help them survive summer drought. In myth, Athena gave the olive tree to Athens.'),
  mcq('ae.tourism', 'aegean', 'Mira notices that Santorini is packed with cruise passengers in summer. Which is a NEGATIVE impact of mass tourism on small islands?', [['Pressure on water and housing', true], ['More jobs in hotels and bars', false, 'That is a benefit, though often seasonal.'], ['More money for local restaurants', false, 'A benefit.'], ['Better ferry links to the mainland', false, 'Usually a benefit.']], 'Santorini has introduced limits on cruise ship visitors to manage the pressure.'),
  ...MED.map(([id, name, note]) => ({ id: `geography.med.${id.toLowerCase()}`, topic: 'geography.aegean', kind: 'mapfact', map: 'europe', layer: 'countries', feature: id, answer: name, accept: [], choosePrompt: ['MKD', 'BGR'].includes(id) ? 'Which of Greece’s northern neighbours is highlighted?' : 'Which Mediterranean country is highlighted?', explain: `This is ${the(name)}. ${note}` })),

  // --- world places
  ...PLACES.flatMap(([id, name, capital, wrong, note, acceptName, acceptCap]) => [
    { id: `geography.pl.${id.toLowerCase()}`, topic: 'geography.places', kind: 'mapfact', map: 'world', layer: 'countries', feature: id, zoom: ZOOM[CONT[id]], answer: name.replace(/^the /, '').replace(/^./, (c) => c.toUpperCase()), accept: [name, ...acceptName], choosePrompt: 'Which country is highlighted?', explain: `This is ${the(name)}. ${note}` },
    fact(`plc.${id.toLowerCase()}`, 'places', `What is the capital of ${the(name)}?`, capital, wrong, `The capital of ${the(name)} is ${capital.replace(/\.$/, '')}. ${note}`, {
      map: 'world', layer: 'countries', feature: id, zoom: ZOOM[CONT[id]], fill: true, accept: acceptCap, ...(capital.length > 20 ? C : {}),
      learn: `The capital of **${the(name)}** is **${capital}**. ${note}`,
    }),
  ]),

  // --- hazard management (stretch)
  mcq('hm.ps', 'hazard-management', 'What are the “three Ps” of hazard management?', [['Prediction, protection and preparation', true], ['Plates, pressure and power supplies', false, 'Not a framework.'], ['Planning, policing and payment', false, 'Planning is close, but the three Ps are prediction, protection and preparation.'], ['People, places and emergency plans', false, 'Not the standard terms.']], 'Predict (monitor), protect (build to resist), prepare (drills, kits, plans).'),
  mcq('hm.predict', 'hazard-management', 'Which can scientists use to help PREDICT a volcanic eruption?', [['Tiny earthquakes and gas', true], ['Unusual animal behaviour alone', false, 'Animal behaviour is not reliable enough on its own.'], ['The phase of the Moon and the tides', false, 'No reliable link.'], ['Nothing: eruptions give no warning', false, 'Many eruptions give warning signs.']], 'Earthquakes still cannot be predicted precisely, but many eruptions can.'),
  mcq('hm.protect', 'hazard-management', 'Which is an example of PROTECTION against earthquakes?', [['Buildings with shock absorbers', true], ['An evacuation drill at school', false, 'That is preparation.'], ['A network of seismometers', false, 'That is monitoring (prediction).'], ['Moving away from the coast', false, 'That is avoidance, not protection.']], 'Tokyo’s tall buildings are designed to sway rather than snap.'),
  mcq('hm.compare', 'hazard-management', 'Why do lower-income countries often suffer more deaths from similar hazards?', [['Less money for strong buildings', true], ['Their earthquakes are always bigger', false, 'Magnitude does not depend on wealth.'], ['Their hazards happen more often', false, 'Frequency is not the key difference: wealth and preparation are.'], ['They have more plate boundaries', false, 'Wealth, not geology, is the key difference here.']], 'Higher-income countries often suffer greater economic losses but fewer deaths.'),
  mcq('hm.japan-drill', 'hazard-management', 'Every year on 1 September, Japan holds Disaster Prevention Day with drills. This is an example of…', [['preparation', true], ['prediction', false, 'Drills prepare people; they do not predict.'], ['protection', false, 'Protection is about structures.'], ['mitigation of climate change', false, 'Different topic.']], 'The date marks the 1923 Great Kantō earthquake.'),
  mcq('hm.risk', 'hazard-management', 'Hazard risk is often described as hazard × vulnerability ÷ capacity to cope. What does “vulnerability” mean?', [['How easily people are harmed', true], ['How big the earthquake or eruption is', false, 'That is the hazard.'], ['How fast rescue teams arrive', false, 'That is capacity to cope.'], ['How often the hazard happens', false, 'That is about the hazard itself, not the people.']], 'Reducing vulnerability is often the most effective way to reduce deaths.'),

  // --- numbers in geography (stretch)
  fact('nm.median', 'numbers', 'Rainfall (mm) for five days: 2, 0, 15, 3, 1. What is the median?', '2', ['4.2', '15', '3'], 'Order them: 0, 1, 2, 3, 15. The middle value is 2. (The mean, 4.2, is dragged up by the one wet day.)'),
  fact('nm.mean', 'numbers', 'Temperatures (°C) on five days: 12, 15, 14, 11, 13. What is the mean?', '13', ['14', '12', '65'], 'Total 65 ÷ 5 = 13.'),
  fact('nm.range', 'numbers', 'Populations of four villages: 340, 1,200, 560, 890. What is the range?', '860', ['1200', '1540', '730'], 'Range = largest − smallest = 1,200 − 340 = 860.'),
  mcq('nm.iqr', 'numbers', 'Why is the interquartile range (IQR) often better than the range?', [['Extreme values do not affect it', true], ['It is always bigger than the range', false, 'It is usually smaller.'], ['It includes every value equally', false, 'It deliberately ignores the top and bottom quarters.'], ['It is quicker to work out by hand', false, 'It is not quicker, and speed is not a statistical reason.']], 'IQR = upper quartile − lower quartile.'),
  mcq('nm.scatter', 'numbers', 'A scatter graph shows that countries with higher GNI per head tend to have higher life expectancy. This is…', [['a positive correlation', true], ['a negative correlation', false, 'Both go up together, so it is positive.'], ['no correlation', false, 'There is a clear pattern.'], ['proof that money causes long life', false, 'Correlation does not prove causation.']], 'Correlation shows a relationship; explaining the cause needs more evidence.'),
  mcq('nm.choropleth', 'numbers', 'What is a choropleth map?', [['Areas shaded by value', true], ['A map with contour lines', false, 'That is a relief map.'], ['A map of the ocean floor', false, 'That is a bathymetric map.'], ['Dots placed for each event', false, 'It is about shading by value.']], 'Use darker shades for higher values, and always include a key.'),
  mcq('nm.mode', 'numbers', 'Kit records the weather on ten days: sun, rain, rain, cloud, rain, sun, cloud, rain, sun, rain. What is the mode?', [['rain', true], ['sun', false, 'Sun appears 3 times; rain 5 times.'], ['cloud', false, 'Cloud appears only twice.'], ['There is no mode', false, 'The most frequent value is rain.']], 'The mode is the most common value: the only average that works for categories like this.'),

  // --- drainage basins (stretch)
  fact('db.watershed', 'basins', 'The boundary of a drainage basin, usually along high ground, is called the…', 'watershed', ['confluence', 'source', 'floodplain'], 'Rain falling on either side of the watershed ends up in different rivers.', { accept: ['the watershed'] }),
  fact('db.confluence', 'basins', 'The point where two rivers meet is called a…', 'confluence', ['watershed', 'tributary', 'meander'], 'A tributary is a smaller river that joins the main river at a confluence.', { accept: ['a confluence'] }),
  mcq('db.infiltration', 'basins', 'What is infiltration?', [['Water soaking into the soil', true], ['Water moving through rock deep underground', false, 'That is percolation and groundwater flow.'], ['Water flowing over the surface', false, 'That is surface runoff (overland flow).'], ['Water evaporating', false, 'That is an output.']], 'Flows: infiltration, percolation, throughflow, surface runoff, groundwater flow.'),
  order('db.system', 'basins', 'Match each part of the drainage basin system to its role: precipitation, interception by trees, surface runoff, river discharge into the sea.', ['precipitation', 'interception by trees', 'surface runoff', 'river discharge into the sea'], ['input', 'store', 'flow', 'output'], 'Inputs enter, stores hold water for a while, flows move it, outputs leave the basin.'),
  mcq('db.lag', 'basins', 'On a storm hydrograph, what is the lag time?', [['The gap between peak rain and peak flow', true], ['How long the storm lasts in total', false, 'That is the storm’s duration.'], ['How long the river stays in flood', false, 'Not quite.'], ['The time until the river level falls again', false, 'That is the falling limb, not the lag time.']], 'A short lag time means the river rises quickly: a higher flood risk.'),
  mcq('db.urban', 'basins', 'Why does an urban area usually have a shorter lag time than a forested area?', [['Concrete and drains speed up runoff', true], ['Cities get much less rain', false, 'They get similar or more.'], ['Trees make rain fall faster', false, 'Trees slow water down by interception.'], ['Rivers in cities are longer', false, 'Length is not the reason.']], 'Impermeable surfaces increase runoff; that is why sustainable drainage (SuDS) uses ponds and green roofs.'),
];

